 * Registers policy rules governing the browser agent's tools.
 *
 * - Read-only tools (snapshots, screenshots, page listing) are always ALLOWed.
 * - When `confirmSensitiveActions` is enabled, sensitive tools (fill,
 *   upload_file, evaluate_script) require user confirmation (ASK_USER).
 * - A rule for `fill` is always registered regardless of configuration.
 */
function registerBrowserPolicyRules(
  config: Config,
  customConfig: BrowserAgentCustomConfig | undefined,
): void {
  const policyEngine = config.getPolicyEngine();
  if (!policyEngine) {
    return;
  }

  const confirmSensitiveActions = customConfig?.confirmSensitiveActions === true;

  // Clean up any rules previously registered by this factory so repeated
  // invocations stay idempotent.
  for (const toolName of [...READ_ONLY_TOOLS, ...SENSITIVE_TOOLS]) {
    policyEngine.removeRulesForTool(
      qualifiedToolName(toolName),
      BROWSER_POLICY_SOURCE,
    );
  }

  // Read-only tools are always allowed.
  for (const toolName of READ_ONLY_TOOLS) {
    policyEngine.addRule({
      toolName: qualifiedToolName(toolName),
      mcpName: BROWSER_AGENT_NAME,
      decision: PolicyDecision.ALLOW,
      priority: PRIORITY_SUBAGENT_TOOL,
      source: BROWSER_POLICY_SOURCE,
    });
  }

  if (confirmSensitiveActions) {
    // Require confirmation for each sensitive tool.
    for (const toolName of SENSITIVE_TOOLS) {
      policyEngine.addRule({
        toolName: qualifiedToolName(toolName),
        mcpName: BROWSER_AGENT_NAME,
        decision: PolicyDecision.ASK_USER,
        priority: 999,
        source: BROWSER_POLICY_SOURCE,
