    }
  } else {
    // `fill` always has a rule; when confirmation is disabled it is allowed
    // like the other interactive browser tools.
    policyEngine.addRule({
      toolName: qualifiedToolName('fill'),
      mcpName: BROWSER_AGENT_NAME,
      decision: PolicyDecision.ALLOW,
      priority: PRIORITY_SUBAGENT_TOOL,
      source: BROWSER_POLICY_SOURCE,
    });
  }
